class Span(NamedTuple):
    """A marked up region in some text."""

    start: int
    """Span start index."""
    end: int
    """Span end index."""
    style: Union[str, Style]
    """Style associated with the span."""

    def __repr__(self) -> str:
        return f"Span({self.start}, {self.end}, {self.style!r})"

    def __bool__(self) -> bool:
        return self.end > self.start

    def split(self, offset: int) -> Tuple["Span", Optional["Span"]]:
        """Split a span in to 2 from a given offset."""

        if offset < self.start:
            return self, None
        if offset >= self.end:
            return self, None

        start, end, style = self
        span1 = Span(start, min(end, offset), style)
        span2 = Span(span1.end, end, style)
        return span1, span2

    def move(self, offset: int) -> "Span":
        """Move start and end by a given offset.

        Args:
            offset (int): Number of characters to add to start and end.

        Returns:
            TextSpan: A new TextSpan with adjusted position.
        """
        start, end, style = self
        return Span(start + offset, end + offset, style)

    def right_crop(self, offset: int) -> "Span":
        """Crop the span at the given offset.

        Args:
            offset (int): A value between start and end.

        Returns:
            Span: A new (possibly smaller) span.
        """
        start, end, style = self
        if offset >= end:
            return self
        return Span(start, min(offset, end), style)

    def extend(self, cells: int) -> "Span":
        """Extend the span by the given number of cells.

        Args:
            cells (int): Additional space to add to end of span.

        Returns:
            Span: A span.
        """
        if cells:
            start, end, style = self
            return Span(start, end + cells, style)
        else:
            return self


class Text(JupyterMixin):
    """Text with color / style.

    Args:
        text (str, optional): Default unstyled text. Defaults to "".
        style (Union[str, Style], optional): Base style for text. Defaults to "".
        justify (str, optional): Justify method: "left", "center", "full", "right". Defaults to None.
        overflow (str, optional): Overflow method: "crop", "fold", "ellipsis". Defaults to None.
        no_wrap (bool, optional): Disable text wrapping, or None for default. Defaults to None.
        end (str, optional): Character to end text with. Defaults to "\\n".
        tab_size (int): Number of spaces per tab, or `None` to use `console.tab_size`. Defaults to None.
        spans (List[Span], optional). A list of predefined style spans. Defaults to None.
    """

    __slots__ = [
        "_text",
        "style",
        "justify",
        "overflow",
        "no_wrap",
        "end",
        "tab_size",
        "_spans",
        "_length",
    ]

    def __init__(
        self,
        text: str = "",
        style: Union[str, Style] = "",
        *,
        justify: Optional[str] = None,
        overflow: Optional[str] = None,
        no_wrap: Optional[bool] = None,
        end: Optional[str] = None,
        tab_size: Optional[int] = None,
        spans: Optional[List[Span]] = None,
    ):
        self.text = text
        self.style = style
        self.justify = justify
        self.overflow = overflow
        self.no_wrap = no_wrap
        self.end = end if end is not None else "\\n"
        self.tab_size = tab_size
        self._spans = spans if spans is not None else []
        self._length = len(text)

    def __str__(self) -> str:
        return self.text

    def __repr__(self) -> str:
        return f"Text('{self.text!r}')"

    def __len__(self) -> int:
        return self._length

    def __contains__(self, char: str) -> bool:
        return char in self.text

    def __getitem__(self, index: int) -> str:
        return self.text[index]

    def __iter__(self) -> iter:
        return iter(self.text)

    def __add__(self, other: Union[str, "Text"]) -> "Text":
        if isinstance(other, str):
            return Text(self.text + other, self.style)
        if isinstance(other, Text):
            return Text(self.text + other.text, self.style)

        raise TypeError(f"unsupported operand type(s) for +: '{type(self).__name__}' and '{type(other).__name__}'")

    def __mul__(self, other: Union[int, "Text"]) -> "Text":
        if isinstance(other, int):
            return Text(self.text * other, self.style)
        if isinstance(other, Text):
            return Text(self.text * other.text, self.style)

        raise TypeError(f"unsupported operand type(s) for *: '{type(self).__name__}' and '{type(other).__name__}'")

    def __radd__(self, other: Union[str, "Text"]) -> "Text":
        return self.__add__(other)

    def __rmul__(self, other: Union[int, "Text"]) -> "Text":
        return self.__mul__(other)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return False
        return self.text == other.text

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __le__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return NotImplemented
        return self.text <= other.text

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return NotImplemented
        return self.text >= other.text

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return NotImplemented
        return self.text < other.text

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return NotImplemented
        return self.text > other.text

    def to_string(self) -> str:
        return self.text

    def __call__(self, *args, **kwargs) -> str:
        return self.to_string()

    def __format__(self, format_spec: str) -> str:
        return self.text % format_spec

    def __repr__(self) -> str:
        return f"Text('{self.text!r}')"

    def __str__(self) -> str:
        return self.text

    def __hash__(self) -> int:
        return hash(self.text)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Text):
            return False
        return self.text == other.text

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

